          <span>Coverage across key workflows</span>
        </div>
        <div class="stat">
          <strong>1 place</strong>
          <span>Clear intake for product help</span>
        </div>
        <div class="stat">
          <strong>Human-led</strong>
          <span>Thoughtful follow-up when needed</span>
        </div>
      </div>
    </section>

    <section class="form-card" aria-labelledby="support-form-title">
      <h2 id="support-form-title">Contact support</h2>
