        statusMessage.textContent = "Please fix the highlighted fields and try again.";
        statusMessage.dataset.state = "";
        return;
      }

      statusMessage.textContent = "Thanks. Your support request is ready to send.";
      statusMessage.dataset.state = "success";
      form.reset();
      fields.forEach((field) => setFieldState(field, ""));
      submitAttempted = false;
    });
